    12  void encodeUTF8(char *&dst, uint32_t cp) {
    13    char *d = dst;
    14    if (cp <= 0x7F) {
    15      *d = (char)cp;
    16      ++d;
    17    } else if (cp <= 0x7FF) {
    18      d[1] = (cp & 0x3F) | 0x80;
    19      cp >>= 6;
    20      d[0] = (cp & 0x1F) | 0xC0;
    21      d += 2;
    22    } else if (cp <= 0xFFFF) {
    23      d[2] = (cp & 0x3F) | 0x80;
    24      cp >>= 6;
    25      d[1] = (cp & 0x3F) | 0x80;
    26      cp >>= 6;
    27      d[0] = (cp & 0x0F) | 0xE0;
    28      d += 3;
    29    } else if (cp <= 0x1FFFFF) {
    30      d[3] = (cp & 0x3F) | 0x80;
    31      cp >>= 6;
    32      d[2] = (cp & 0x3F) | 0x80;
    33      cp >>= 6;
    34      d[1] = (cp & 0x3F) | 0x80;
    35      cp >>= 6;
    36      d[0] = (cp & 0x07) | 0xF0;
    37      d += 4;
    38    } else if (cp <= 0x3FFFFFF) {
    39      d[4] = (cp & 0x3F) | 0x80;
    40      cp >>= 6;
    41      d[3] = (cp & 0x3F) | 0x80;
    42      cp >>= 6;
    43      d[2] = (cp & 0x3F) | 0x80;
    44      cp >>= 6;
    45      d[1] = (cp & 0x3F) | 0x80;
    46      cp >>= 6;
    47      d[0] = (cp & 0x03) | 0xF8;
    48      d += 5;
    49    } else {
    50      d[5] = (cp & 0x3F) | 0x80;
    51      cp >>= 6;
    52      d[4] = (cp & 0x3F) | 0x80;
    53      cp >>= 6;
    54      d[3] = (cp & 0x3F) | 0x80;
    55      cp >>= 6;
    56      d[2] = (cp & 0x3F) | 0x80;
    57      cp >>= 6;
    58      d[1] = (cp & 0x3F) | 0x80;
    59      cp >>= 6;
    60      d[0] = (cp & 0x01) | 0xFC;
    61      d += 6;
    62    }
    63    dst = d;
